"use strict";(self.webpackChunkphyling_docs=self.webpackChunkphyling_docs||[]).push([[1552],{2182:(t,e,a)=>{a.r(e),a.d(e,{comp:()=>i,data:()=>r});var d=a(641);const o={},i=(0,a(6262).A)(o,[["render",function(t,e){return(0,d.uX)(),(0,d.CE)("div",null,[...e[0]||(e[0]=[(0,d.Fv)('<h1 id="maxi-phyling-rowing" tabindex="-1"><a class="header-anchor" href="#maxi-phyling-rowing"><span>Maxi-Phyling Rowing</span></a></h1><p><strong>The Maxi-Phyling</strong> is the versatile GPS unit for collecting data in rowing. Validated by the International Rowing Federation (World Rowing), it can be used in training as well as in competition. It provides complete feedback on a crew&#39;s performance.</p><p><img src="/assets/img/aviron/test_aviron_crop.jpg" alt="Maxi-Phyling in use during training"></p><p><strong>The Phyling Rowing app</strong> was developed in collaboration with the French Rowing Federation (FFAviron) and the Olympic French team to provide precise analysis of the markers and performance indicators specific to the sport. It gives coaches training feedback through an advanced analysis module to visualize, compare and process data. The app also lets you export data as a report or share it directly on training-tracking platforms such as Nolio.</p><h2 id="quick-start" tabindex="-1"><a class="header-anchor" href="#quick-start"><span>Quick start</span></a></h2><h3 id="mounting-the-unit-on-the-boat" tabindex="-1"><a class="header-anchor" href="#mounting-the-unit-on-the-boat"><span>Mounting the unit on the boat</span></a></h3><ol><li>Firmly attach the Maxi-Phyling to the hull of the boat using a 3M-type Velcro strap</li><li>Make sure the Maxi-Phyling is placed in the boat&#39;s direction of travel</li></ol><div class="hint-container tip"><p class="hint-container-title">Tip</p><p>The Maxi-Phyling can be placed in a waterproof box (such as a food container) to protect it from the elements.</p></div><p><img src="/assets/img/aviron/quickstart.png" alt="Diagram showing how to mount the Maxi-Phyling"></p><h3 id="starting-and-stopping-a-recording" tabindex="-1"><a class="header-anchor" href="#starting-and-stopping-a-recording"><span>Starting and stopping a recording</span></a></h3><ol><li>Turn on the Maxi-Phyling with the ON button (green LED).</li><li>Press the REC button to start recording (blue LED).</li><li>Press the REC button again to end the recording (green LED).</li><li>The data is saved in the Maxi-Phyling and uploaded to the app via USB or Wifi.</li></ol><h3 id="hub-and-real-time-visualization" tabindex="-1"><a class="header-anchor" href="#hub-and-real-time-visualization"><span>Hub and real-time visualization</span></a></h3><ol><li>Turn on the Hub; it connects automatically to the Maxi-Phyling.</li><li>Access the app through the Hub&#39;s Wifi connection. On a PC, tablet or smartphone, enter the address <a href="http://192.168.1.42" target="_blank" rel="noopener noreferrer">http://192.168.1.42</a> in your browser.</li><li>Log in with your username and password.</li><li>Real-time data visualization is available in the Real time tab.</li></ol><h3 id="data-processing-and-export" tabindex="-1"><a class="header-anchor" href="#data-processing-and-export"><span>Data processing and export</span></a></h3><ol><li>Find your recordings in the Data tab (&quot;New data&quot; button) to associate them.</li><li>In the Associated data menu, view a recording, create selections and compare several recordings.</li><li>Export your recordings and comparisons in different formats: PDF report, raw data, CSV format.</li></ol><h2 id="usb-mode-data-upload" tabindex="-1"><a class="header-anchor" href="#usb-mode-data-upload"><span>USB mode &amp; data upload</span></a></h2><p>Here is the procedure to retrieve data from a Maxi-Phyling using USB mode and upload it to the Phyling Cloud app.</p><h3 id="_1-connecting-to-the-pc" tabindex="-1"><a class="header-anchor" href="#_1-connecting-to-the-pc"><span>1. Connecting to the PC</span></a></h3><ul><li><strong>Trigger USB mode</strong> by long-pressing the ON button. The LED turns yellow and the device appears on the computer as a USB drive.</li><li><strong>Plug the USB cable</strong> of the Maxi-Phyling into the computer.</li></ul><h3 id="_2-preparing-the-data-for-import" tabindex="-1"><a class="header-anchor" href="#_2-preparing-the-data-for-import"><span>2. Preparing the data for import</span></a></h3><ul><li><strong>Open the Maxi-Phyling folder</strong> named SD.</li><li><strong>Open the &quot;data&quot; folder</strong>. Files are sorted in chronological order, with a name like <code>157_1_20240125_161803</code> where:</li></ul><table><thead><tr><th>157</th><th>1</th><th>20240125</th><th>161803</th></tr></thead><tbody><tr><td>Maxi-Phyling number</td><td>Recording number</td><td>Recording date (25/01/2024)</td><td>Recording time (16:18:03)</td></tr></tbody></table><ul><li><strong>Copy the desired .txt file</strong> to the computer desktop or to the folder of your choice.</li></ul><h3 id="_3-importing-the-data-into-the-phyling-app" tabindex="-1"><a class="header-anchor" href="#_3-importing-the-data-into-the-phyling-app"><span>3. Importing the data into the Phyling app</span></a></h3><ul><li><strong>Open a web browser</strong> and go to the Phyling app with your username and password: <a href="https://app.phyling.fr" target="_blank" rel="noopener noreferrer">https://app.phyling.fr</a>.</li><li><strong>Import the file</strong>: <ul><li>Click the cloud icon in the &quot;Data&quot; tab.</li><li>Look for your file in the &quot;data&quot; folder of your Maxi-Phyling or in the folder on the computer where it is stored. Identify the recording by its start date and time.</li><li>Fill in the file&#39;s association parameters (Group, Athlete(s), Sport = Rowing, Exercise, Boat type, etc.) and click the &quot;Import&quot; button.</li></ul></li></ul><p><img src="/assets/img/aviron/data-upload.png" alt="Data import window"></p><h3 id="_4-completing-the-import" tabindex="-1"><a class="header-anchor" href="#_4-completing-the-import"><span>4. Completing the import</span></a></h3><ul><li>The file appears at the top of the data list.</li><li>A &quot;…&quot; icon indicates that the file is being imported.</li><li>If a &quot;!&quot; icon appears, check the association parameters before restarting the analysis.</li></ul><h3 id="_5-data-analysis" tabindex="-1"><a class="header-anchor" href="#_5-data-analysis"><span>5. Data analysis</span></a></h3><ul><li><strong>Creating a selection</strong>: <ul><li><strong>Make a precise selection</strong> using the zoom tools and the indicators of your choice (stroke rate, acceleration, instantaneous speed, etc.). Hover over the curve to find the time or distance shown at the start of the selection. Enter this value in the selection tool below the graph, in &quot;x0&quot;. Then enter the distance or duration of the selection in &quot;dx&quot;. When you check this selection, an automatic zoom on your race appears.</li><li><strong>Save the selection</strong> by clicking the &quot;+&quot; button.</li><li><strong>Export a PDF report</strong> of this selection with the download icon at the top right of your graph. Select the &quot;PDF report&quot; format and the number of your selection.</li></ul></li><li><strong>Visualization in the Phyling app</strong>: <ul><li>Use the automatic template located above your graph. By default, you will find the <code>Speed-Stroke rate</code>, <code>Speed-Acceleration</code>, <code>Accelerations</code>, <code>Catch check index</code> and <code>Angles</code> graphs.</li><li>Use the <code>All</code> template to create your own graph. Use the graphical tools to add other indicators on a second y-axis and across several graphs.</li></ul></li><li><strong>Comparing several selections</strong>: <ul><li><strong>Make several selections</strong>.</li><li><strong>In the Data tab</strong>, tick the box to the left of your recording to select it and click the comparison icon at the top right. You can compare several recordings and selections from different recordings.</li><li>In the comparison interface, <strong>tick the selections to compare</strong> and choose the indicators to display.</li></ul></li></ul><h2 id="data" tabindex="-1"><a class="header-anchor" href="#data"><span>Data</span></a></h2><p>The data recorded and calculated by the Maxi-Phyling in rowing configuration provides complete information on the rowing cycle, speed and boat stability. To make the most of this data, Phyling makes the raw data of each sensor available. Phyling has also developed specific analyses to calculate certain indicators.</p><h5 id="sampling-frequencies" tabindex="-1"><a class="header-anchor" href="#sampling-frequencies"><span>Sampling frequencies</span></a></h5><table><thead><tr><th>Sensor</th><th>Frequency</th></tr></thead><tbody><tr><td>IMU</td><td>100Hz</td></tr><tr><td>GPS</td><td>10Hz</td></tr></tbody></table><p>The tables below describe the calculated variables and indicators, as well as how they were obtained.</p><h3 id="csv-file-data" tabindex="-1"><a class="header-anchor" href="#csv-file-data"><span>CSV file data</span></a></h3><p>This data is included in the csv file that can be downloaded from the app. It is time-series data sampled at 100Hz, including both raw and calculated data. This is also the data displayed as graphs in the app.</p><table><thead><tr><th>Variable</th><th>Description</th><th>Unit</th><th>Calculation</th></tr></thead><tbody><tr><td>T</td><td>Time since the start of the recording</td><td>s</td><td></td></tr><tr><td>D</td><td>Distance traveled</td><td>m</td><td>Calculated using the <a href="https://en.wikipedia.org/wiki/Vincenty%27s_formulae" target="_blank" rel="noopener noreferrer">Vincenty method</a></td></tr><tr><td>T_norm</td><td>Time normalized per stroke</td><td>stroke</td><td></td></tr><tr><td>gyro_x</td><td>Angular velocity around the x axis (boat axis)</td><td>deg/s</td><td>High-pass filter (fc=0.2Hz, order=5)</td></tr><tr><td>gyro_y</td><td>Angular velocity around the y axis (lateral axis)</td><td>deg/s</td><td>High-pass filter (fc=0.2Hz, order=5)</td></tr><tr><td>gyro_z</td><td>Angular velocity around the z axis (vertical axis)</td><td>deg/s</td><td>High-pass filter (fc=0.2Hz, order=5)</td></tr><tr><td>acc_x</td><td>Acceleration along the x axis (boat axis)</td><td>m/s²</td><td>Raw data</td></tr><tr><td>acc_y</td><td>Acceleration along the y axis (lateral axis)</td><td>m/s²</td><td>Raw data</td></tr><tr><td>acc_z</td><td>Acceleration along the z axis (vertical axis)</td><td>m/s²</td><td>Raw data</td></tr><tr><td>roll</td><td>Roll</td><td>deg</td><td>Obtained by integrating the gyro data (positive when the boat leans to port and negative when it leans to starboard)</td></tr><tr><td>pitch</td><td>Pitch</td><td>deg</td><td>Obtained by integrating the gyro data (positive when the bow rises and negative when the stern rises)</td></tr><tr><td>yaw</td><td>Yaw</td><td>deg</td><td>Obtained by integrating the gyro data (positive when the boat turns to port and negative when it turns to starboard)</td></tr><tr><td>heave</td><td>Heave (vertical oscillation distance of the boat)</td><td>cm</td><td>Obtained by double integration of <code>acc_z</code> (<a href="https://www.sciencedirect.com/science/article/pii/S1474667016432192" target="_blank" rel="noopener noreferrer">Richter et al. 2014</a>)</td></tr><tr><td>acc_z_</td><td>Acceleration along the z axis without gravity</td><td>m/s²</td><td><code>acc_z - g</code></td></tr><tr><td>gpsTimeUs</td><td>GPS timestamp in microseconds since 1970</td><td>microsecond</td><td>Raw data</td></tr><tr><td>gpsTimeAccuracyNs</td><td>GPS time accuracy</td><td>nanosecond</td><td>Raw data</td></tr><tr><td>longitude</td><td>Longitude</td><td>deg</td><td>Raw data</td></tr><tr><td>latitude</td><td>Latitude</td><td>deg</td><td>Raw data</td></tr><tr><td>speed_gps</td><td>Speed</td><td>m/s</td><td>Raw data</td></tr><tr><td>altitude</td><td>Altitude</td><td>m</td><td>Raw data</td></tr><tr><td>heading</td><td>Heading</td><td>deg</td><td>Raw data</td></tr><tr><td>nSat</td><td>Number of satellites</td><td></td><td>Raw data</td></tr><tr><td>PDOP</td><td><a href="https://en.wikipedia.org/wiki/Dilution_of_precision_(navigation)" target="_blank" rel="noopener noreferrer">Position (3D) dilution of precision</a></td><td></td><td>Raw data</td></tr><tr><td>speed</td><td>Filtered speed</td><td>m/s</td><td>Obtained from the GPS coordinates (latitude, longitude). Low-pass filter (fc=0.1Hz, order=2)</td></tr><tr><td>speed_i</td><td>Instantaneous speed</td><td>m/s</td><td>Fusion algorithm combining the GPS speed <code>speed</code> and the acceleration <code>acc_x</code></td></tr><tr><td>speed_rel</td><td>Relative speed defined against the target speed (depending on the category)</td><td>%</td><td><code>speed / prog_speed</code></td></tr><tr><td>speed_rel_i</td><td>Relative instantaneous speed defined against the target speed (depending on the category)</td><td>%</td><td><code>speed_i / prog_speed</code></td></tr><tr><td>motif_id</td><td>Unique identifier for each stroke</td><td></td><td>Stroke detection from the <code>acc_x</code> acceleration signal</td></tr><tr><td>cadence</td><td>Stroke rate in strokes/min</td><td>spm</td><td><code>1/T_cycle</code> where <code>T_cycle</code> is the duration of one rowing stroke</td></tr><tr><td>pic_acc</td><td>Acceleration peak</td><td>m/s²</td><td><code>max(acc_x)</code> for each rowing stroke</td></tr><tr><td>pic_down</td><td>Deceleration peak</td><td>m/s²</td><td><code>min(acc_x)</code> for each rowing stroke</td></tr><tr><td>t_acc</td><td>Duration of the acceleration phase</td><td>s</td><td><code>T[acc_x &gt; 0]</code> for each rowing stroke</td></tr><tr><td>t_down</td><td>Duration of the deceleration phase</td><td>s</td><td><code>T[acc_x &lt; 0]</code> for each rowing stroke</td></tr><tr><td>t_check</td><td>Catch check index (deceleration duration at the catch)</td><td>s</td><td></td></tr><tr><td>ratio_down</td><td>Total deceleration ratio</td><td>%</td><td><code>t_down/T_cycle</code></td></tr><tr><td>ratio_check</td><td>Deceleration ratio at the catch</td><td>%</td><td><code>t_check/T_cycle</code></td></tr><tr><td>amp_roll</td><td>Roll amplitude</td><td>deg</td><td><code>max(roll) - min(roll)</code> for each rowing stroke</td></tr><tr><td>amp_pitch</td><td>Pitch amplitude</td><td>deg</td><td><code>max(pitch) - min(pitch)</code> for each rowing stroke</td></tr><tr><td>amp_heave</td><td>Heave amplitude</td><td>cm</td><td><code>max(heave) - min(heave)</code> for each rowing stroke</td></tr><tr><td>d_stroke</td><td>Distance per stroke</td><td>m</td><td>Calculated from speed and stroke rate</td></tr><tr><td>timestamp</td><td><a href="https://en.wikipedia.org/wiki/Unix_time" target="_blank" rel="noopener noreferrer">Timestamp since 1970</a></td><td>s</td><td>If GPS is available, simple conversion of gpsTimeUs; otherwise the Maxi-Phyling time is used</td></tr></tbody></table><h3 id="indicators" tabindex="-1"><a class="header-anchor" href="#indicators"><span>Indicators</span></a></h3><p>Indicators are statistics that characterize a whole selection. In the app, they appear in the &quot;Indicators&quot; table and also on the first page of the pdf reports.</p><table><thead><tr><th>Variable</th><th>Description</th><th>Unit</th><th>Calculation</th></tr></thead><tbody><tr><td>D_true</td><td>True distance</td><td>m</td><td>Information provided by the user</td></tr><tr><td>D_MP</td><td>Maxi-Phyling distance</td><td>m</td><td><code>D[-1] - D[0]</code> over the selection</td></tr><tr><td>T_chrono</td><td>Chrono time</td><td></td><td>Information provided by the user</td></tr><tr><td>T_MP</td><td>Maxi-Phyling time</td><td></td><td><code>T[-1] - T[0]</code> over the selection</td></tr><tr><td>T_500m</td><td>Average time per 500m</td><td></td><td><code>500m / v_moy</code></td></tr><tr><td>v_moy</td><td>Average speed</td><td>m/s</td><td><code>D_true/T_chrono</code> if this data is provided, otherwise <code>D_MP/T_MP</code></td></tr><tr><td>v_moy_rel</td><td>Average relative speed</td><td>%</td><td><code>v_moy / prog_speed</code></td></tr><tr><td>v_max</td><td>Maximum speed</td><td>m/s</td><td><code>max(v)</code></td></tr><tr><td>n_strokes</td><td>Number of strokes taken during the selection</td><td></td><td>From <code>cad_moy</code> and <code>T_MP</code></td></tr><tr><td>d_stroke</td><td>Average distance per stroke</td><td>m</td><td><code>(Total distance) / n_strokes</code></td></tr><tr><td>cad_moy</td><td>Average stroke rate</td><td>spm</td><td><code>moy(cadence)</code></td></tr><tr><td>cad_min</td><td>Min stroke rate</td><td>spm</td><td><code>min(cadence)</code></td></tr><tr><td>cad_max</td><td>Max stroke rate</td><td>spm</td><td><code>max(cadence)</code></td></tr><tr><td>ratio_down_moy</td><td>Average total deceleration ratio</td><td>%</td><td><code>moy(ratio_down)</code></td></tr><tr><td>ratio_check_moy</td><td>Average deceleration ratio at the catch</td><td>%</td><td><code>moy(ratio_check)</code></td></tr></tbody></table><h2 id="pdf-report" tabindex="-1"><a class="header-anchor" href="#pdf-report"><span>PDF report</span></a></h2><p>The rowing analysis report gives coaches a wealth of information to analyze the performance of their boats in training or in competition. It provides indicators as values and graphs, including the stroke rate-speed profile over the whole race, the boat&#39;s acceleration map and a breakdown of the race into segments.</p><p><img src="/assets/img/aviron/report.png" alt="Example of a race report"></p><p>This valuable tool allows coaches to make informed decisions to optimize training and maximize results in upcoming races.</p>',45)])])}]]),r=JSON.parse('{"path":"/en/products/maxi-aviron.html","title":"Maxi-Phyling Rowing","lang":"en-US","frontmatter":{"description":"Maxi-Phyling Rowing The Maxi-Phyling is the versatile GPS unit for collecting data in rowing. Validated by the International Rowing Federation (World Rowing), it can be used in ...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"Maxi-Phyling Rowing\\",\\"image\\":[\\"https://docs.phyling.fr/staging/assets/img/aviron/test_aviron_crop.jpg\\",\\"https://docs.phyling.fr/staging/assets/img/aviron/quickstart.png\\",\\"https://docs.phyling.fr/staging/assets/img/aviron/data-upload.png\\",\\"https://docs.phyling.fr/staging/assets/img/aviron/report.png\\"],\\"dateModified\\":\\"2026-10-01T14:49:06.000Z\\",\\"author\\":[]}"],["meta",{"property":"og:url","content":"https://docs.phyling.fr/staging/en/products/maxi-aviron.html"}],["meta",{"property":"og:site_name","content":"Phyling docs"}],["meta",{"property":"og:title","content":"Maxi-Phyling Rowing"}],["meta",{"property":"og:description","content":"Maxi-Phyling Rowing The Maxi-Phyling is the versatile GPS unit for collecting data in rowing. Validated by the International Rowing Federation (World Rowing), it can be used in ..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://docs.phyling.fr/staging/assets/img/aviron/test_aviron_crop.jpg"}],["meta",{"property":"og:locale","content":"en-US"}],["meta",{"property":"og:locale:alternate","content":"fr-FR"}],["meta",{"property":"og:updated_time","content":"2026-10-01T14:49:06.000Z"}],["meta",{"property":"article:modified_time","content":"2026-10-01T14:49:06.000Z"}],["link",{"rel":"alternate","hreflang":"fr-fr","href":"https://docs.phyling.fr/staging/products/maxi-aviron.html"}]]},"git":{"createdTime":1790866146000,"updatedTime":1790866146000,"contributors":[{"name":"Claude","username":"Claude","email":"noreply@anthropic.com","commits":1,"url":"https://github.com/Claude"},{"name":"Claude Sonnet 5.5","username":"","email":"noreply@anthropic.com","commits":1}]},"readingTime":{"minutes":5.74,"words":1721},"filePathRelative":"en/products/maxi-aviron.md","autoDesc":true}')}}]);